-- 720: actor -> organization in the database's own names (GHUS decision, 24 Nov 2026).
--
-- Stage 1 of 2. Generated by migrations/proposed/organization_720/generate.py from a
-- local copy of production; see that folder's README for the apply sequence.
--
--   * 21 tables and 6 views named actor are renamed (actor -> organization,
--     hub_actor -> hub_organization ...), with their 47 columns named actor
--     (actor_id -> organization_id ...), and the constraint, index, trigger and
--     policy names on them.
--   * Each old name stays as a stand-in VIEW with the old column names, so every
--     query, insert, update and delete the platform and the agents send today runs
--     unchanged (writes pass through to the renamed table; its triggers still run).
--     The stand-ins run with the caller's rights (security_invoker) and Supabase's
--     public roles anon and authenticated have no access to them.
--   * The functions that name these relations are rewritten with the new names and
--     renamed where their name says actor; the originals are saved in
--     compass.migration_snapshot for the rollback, with every rename made.
--   * The category label 'Company / Corporate Actor' reads 'Company / Corporate Organization'.
--
-- Not in stage 1 (stage 2, with the code): internal type codes ('actor' in
-- entity_type, verify_actor, create_actor), the session key ghus.actor_is_human, and
-- the columns named actor in tables that keep their names (event.host_actor_id ...).
--
-- One transaction: any failure changes nothing. Refuses unless the catalog is exactly
-- the one this was generated from.

BEGIN;
SET LOCAL lock_timeout = '15s';

DO $guard$
DECLARE found text; fns text;
BEGIN
    IF to_regclass('compass.migration_snapshot') IS NULL THEN
        RAISE EXCEPTION '720 refused: migration 710 (compass.migration_snapshot) is not applied';
    END IF;
    IF EXISTS (SELECT 1 FROM public.architecture_v2_migration_ledger WHERE migration_id = '720') THEN
        RAISE EXCEPTION '720 refused: already in the ledger';
    END IF;
    IF EXISTS (SELECT 1 FROM pg_class WHERE relnamespace = 'public'::regnamespace
                AND relname LIKE '%organization%' AND relkind IN ('r','v','m')) THEN
        RAISE EXCEPTION '720 refused: a relation named organization already exists';
    END IF;
    SELECT string_agg(relname || ':' || relkind::text, ', ' ORDER BY relkind, relname) INTO found
      FROM pg_class WHERE relnamespace = 'public'::regnamespace
       AND relname LIKE '%actor%' AND relkind IN ('r','v','m');
    IF found IS DISTINCT FROM 'actor:r, actor_category_definition:r, actor_category_migration_audit:r, actor_category_type_definition:r, actor_details:r, actor_evaluation:r, actor_fact:r, actor_fact_current_pointer:r, actor_location:r, actor_merge_log:r, actor_person:r, actor_ranking:r, actor_relevance:r, actor_sector:r, actor_strategic_connection_check:r, actor_topic:r, actor_update_subscription:r, actor_update_subscription_run:r, actor_verification_event:r, hub_actor:r, hub_actor_removed:r, actor_descendant_edge:v, actor_descendants:v, actor_fact_current:v, actor_fact_current_v2:v, actor_fact_history:v, actor_read:v' THEN
        RAISE EXCEPTION '720 refused: the relations named actor differ from the reviewed ones: %', found;
    END IF;
    SELECT string_agg(proname || '=' || md5(prosrc), ' ' ORDER BY proname) INTO fns
      FROM pg_proc WHERE pronamespace = 'public'::regnamespace
       AND proname IN ('ghus_actor_details_on_pointer', 'ghus_actor_details_on_topicless_fact', 'ghus_actor_details_refresh', 'ghus_guard_actor_status', 'ghus_guard_ranking_is_university', 'ghus_guard_subscription_run_append_only', 'ghus_prevent_actor_family_cycle', 'ghus_project_actor_verification_status', 'ghus_validate_entity_edge');
    IF fns IS DISTINCT FROM 'ghus_actor_details_on_pointer=37ae364a093c6d23fd4e43f536f01e35 ghus_actor_details_on_topicless_fact=37ae364a093c6d23fd4e43f536f01e35 ghus_actor_details_refresh=4d110357f4d926eaaf183a77d42704e7 ghus_guard_actor_status=d0db9ea0cf0ad4bfc2e68bc24f96a8b6 ghus_guard_ranking_is_university=c3e5f2ac92cb3e426ad2fdba8c21fbe9 ghus_guard_subscription_run_append_only=eeddb6cb99d0516f98c54dfc10822413 ghus_prevent_actor_family_cycle=c15c963372cfd4dfc1a2f7103bd98de5 ghus_project_actor_verification_status=3ec5ab6b24677b47762fff28ba4421ae ghus_validate_entity_edge=7992747063b1dc270cc91eede526fa1f' THEN
        RAISE EXCEPTION '720 refused: functions differ from the reviewed ones: %', fns;
    END IF;
END $guard$;

-- The functions as they are, for the rollback (restored byte for byte).
INSERT INTO compass.migration_snapshot (migration_id, object_name, definition)
SELECT '720', 'public.' || p.proname || '(' || pg_get_function_identity_arguments(p.oid) || ')',
       pg_get_functiondef(p.oid)
  FROM pg_proc p
 WHERE p.pronamespace = 'public'::regnamespace
   AND p.proname IN ('ghus_actor_details_on_pointer', 'ghus_actor_details_on_topicless_fact', 'ghus_actor_details_refresh', 'ghus_guard_actor_status', 'ghus_guard_ranking_is_university', 'ghus_guard_subscription_run_append_only', 'ghus_prevent_actor_family_cycle', 'ghus_project_actor_verification_status', 'ghus_validate_entity_edge');

-- Every rename, recorded so the rollback reverses exactly these and nothing else.
