-- 3. Constraint, index, trigger and policy names on them that say actor (a name that
--    would pass PostgreSQL's 63 characters is kept as it is).
DO $names$
DECLARE r record; target text;
BEGIN
    FOR r IN SELECT c.conname AS old, c.conrelid::regclass::text AS rel
               FROM pg_constraint c
              WHERE c.connamespace = 'public'::regnamespace AND c.conname LIKE '%actor%'
                AND c.conrelid::regclass::text = ANY ('{organization,organization_category_definition,organization_category_migration_audit,organization_category_type_definition,organization_details,organization_evaluation,organization_fact,organization_fact_current_pointer,organization_location,organization_merge_log,organization_person,organization_ranking,organization_relevance,organization_sector,organization_strategic_connection_check,organization_topic,organization_update_subscription,organization_update_subscription_run,organization_verification_event,hub_organization,hub_organization_removed}'::text[]) LOOP
        target := replace(r.old, 'actor', 'organization');
        CONTINUE WHEN length(target) > 63;
        EXECUTE format('ALTER TABLE public.%I RENAME CONSTRAINT %I TO %I', r.rel, r.old, target);
        INSERT INTO _renames VALUES ('constraint', r.rel, r.old, target);
    END LOOP;
    FOR r IN SELECT i.relname AS old, t.relname AS rel
               FROM pg_index x JOIN pg_class i ON i.oid = x.indexrelid JOIN pg_class t ON t.oid = x.indrelid
              WHERE t.relnamespace = 'public'::regnamespace AND i.relname LIKE '%actor%'
                AND t.relname = ANY ('{organization,organization_category_definition,organization_category_migration_audit,organization_category_type_definition,organization_details,organization_evaluation,organization_fact,organization_fact_current_pointer,organization_location,organization_merge_log,organization_person,organization_ranking,organization_relevance,organization_sector,organization_strategic_connection_check,organization_topic,organization_update_subscription,organization_update_subscription_run,organization_verification_event,hub_organization,hub_organization_removed}'::text[]) LOOP
        target := replace(r.old, 'actor', 'organization');
        CONTINUE WHEN length(target) > 63;
        EXECUTE format('ALTER INDEX public.%I RENAME TO %I', r.old, target);
        INSERT INTO _renames VALUES ('index', r.rel, r.old, target);
    END LOOP;
    FOR r IN SELECT tg.tgname AS old, c.relname AS rel
               FROM pg_trigger tg JOIN pg_class c ON c.oid = tg.tgrelid
              WHERE NOT tg.tgisinternal AND c.relnamespace = 'public'::regnamespace
                AND tg.tgname LIKE '%actor%'
                AND c.relname = ANY ('{organization,organization_category_definition,organization_category_migration_audit,organization_category_type_definition,organization_details,organization_evaluation,organization_fact,organization_fact_current_pointer,organization_location,organization_merge_log,organization_person,organization_ranking,organization_relevance,organization_sector,organization_strategic_connection_check,organization_topic,organization_update_subscription,organization_update_subscription_run,organization_verification_event,hub_organization,hub_organization_removed}'::text[]) LOOP
        target := replace(r.old, 'actor', 'organization');
        CONTINUE WHEN length(target) > 63;
        EXECUTE format('ALTER TRIGGER %I ON public.%I RENAME TO %I', r.old, r.rel, target);
        INSERT INTO _renames VALUES ('trigger', r.rel, r.old, target);
    END LOOP;
    FOR r IN SELECT p.policyname AS old, p.tablename AS rel FROM pg_policies p
              WHERE p.schemaname = 'public' AND p.policyname LIKE '%actor%'
                AND p.tablename = ANY ('{organization,organization_category_definition,organization_category_migration_audit,organization_category_type_definition,organization_details,organization_evaluation,organization_fact,organization_fact_current_pointer,organization_location,organization_merge_log,organization_person,organization_ranking,organization_relevance,organization_sector,organization_strategic_connection_check,organization_topic,organization_update_subscription,organization_update_subscription_run,organization_verification_event,hub_organization,hub_organization_removed}'::text[]) LOOP
        target := replace(r.old, 'actor', 'organization');
        CONTINUE WHEN length(target) > 63;
        EXECUTE format('ALTER POLICY %I ON public.%I RENAME TO %I', r.old, r.rel, target);
        INSERT INTO _renames VALUES ('policy', r.rel, r.old, target);
    END LOOP;
END $names$;

