UPDATE public.organization_category_definition
   SET display_name = replace(display_name, 'Corporate Actor', 'Corporate Organization')
 WHERE display_name LIKE '%Corporate Actor%';

-- 7. Keep the renames for the rollback.
INSERT INTO compass.migration_snapshot (migration_id, object_name, definition)
SELECT '720', 'rename:' || kind || ':' || COALESCE(rel, '') || ':' || old, new FROM _renames;

COMMIT;
